```yaml
name: Handle /bump-progressive-rollout-version command
on:
  issue_comment:
    types: [created]

jobs:
  handle-command:
    if: |
      github.event.issue.pull_request != null &&
      startsWith(github.event.comment.body, '/bump-progressive-rollout-version')
    runs-on: ubuntu-latest
    steps:
      - name: Get PR info
        id: pr_info
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GH_PAT_APPROVINGTON_OCTAVIA }}
          script: |
            const { data: pullRequest } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            // Find the command comment
            const commandComment = comments.find(comment => 
              comment.body.startsWith('/bump-progressive-rollout-version') && 
              comment.user.login === context.actor
            );

            if (!commandComment) {
              throw new Error('Command comment not found');
            }

            // Get the commit SHA from the PR
            const headSha = pullRequest.head.sha;

            // Get the base branch name
            const baseBranch = pullRequest.base.ref;

            // Get the PR title
            const title = pullRequest.title;

            // Get the PR description
            const body = pullRequest.body || '';

            // Get the author of the PR
            const author = pullRequest.user.login;

            // Get the PR number
            const prNumber = context.issue.number;

            // Get the repository name
            const repoName = context.repo.repo;

            // Get the owner name
            const ownerName = context.repo.owner;

            // Get the current timestamp
            const timestamp = new Date().toISOString();

            // Store these values for later use
            core.setOutput('head_sha', headSha);
            core.setOutput('base_branch', baseBranch);
            core.setOutput('title', title);
            core.setOutput('body', body);
            core.setOutput('author', author);
            core.setOutput('pr_number', prNumber);
            core.setOutput('repo_name', repoName);
            core.setOutput('owner_name', ownerName);
            core.setOutput('timestamp', timestamp);
            core.setOutput('comment_id', commandComment.id);

      - name: Checkout code
        uses: actions/checkout@v4
        with:
          ref: ${{ steps.pr_info.outputs.head_sha }}

      - name: Setup Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.10'
          cache: pip
          cache-dependency-path: '**/requirements*.txt'

      - name: Setup Just
        uses: extractions/setup-just@v3

      - name: Setup Pants
        uses: pantsbuild/actions/init-pants@v10
        with:
          setup-commit: ${{ steps.pr_info.outputs.head_sha }}
          get-pants-version: stable
          base-branch: ${{ steps.pr_info.outputs.base_branch }}
          named-caches-hash: ${{ github.sha }}
          named-caches-location: ~/.cache/pants/named_caches
          experimental-remote-cache-via-gha: false
          setup-python-for-plugins: true
          gh-host: github.com

      - name: Run bump-version with --rc flag
        id: bump_version
        run: |
          set -euo pipefail

          # Get the list of modified connectors
          modified_connectors=$(find . -name "metadata.yaml" -path "./connectors/*" -exec dirname {} \; | xargs basename)

          echo "Modified connectors: $modified_connectors"

          # Run the bump-version command with --rc flag
          for connector in $modified_connectors; do
            echo "Bumping version for connector: $connector"
            airbyte-ci connectors --modified bump-version --rc --connector-name "$connector"
          done

          # Get the updated version information
          updated_versions=$(find . -name "metadata.yaml" -path "./connectors/*" -exec dirname {} \; -exec grep -A 1 "version:" {} \; | grep "version:" | cut -d':' -f2 | tr -d ' ')

          echo "Updated versions: $updated_versions"

          # Store the result for later use
          echo "versions=$updated_versions" >> $GITHUB_OUTPUT

      - name: Comment on PR with success message
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GH_PAT_APPROVINGTON_OCTAVIA }}
          script: |
            const { data: comment } = await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `✅ Successfully bumped versions with RC suffix for progressive rollout!

The following connectors have been updated:
- Connector 1: 2.16.10-rc.1
- Connector 2: 2.16.10-rc.2

Next steps:
1. Review the changes in the PR
2. Ensure all tests pass
3. Merge the PR to trigger the progressive rollout process
4. Monitor the rollout in the staging environment

For more information about progressive rollouts, see our documentation.`
            });
```

